"use client";
import Link from "next/link";
import { useEffect, useState } from "react";
import { ArrowRight, ClipboardCheck } from "lucide-react";
import { api } from "@/lib/api";
import { OpportunityApplication, Page } from "@/lib/types";
export default function ApplicationsPage() { const [items, setItems] = useState<OpportunityApplication[]>([]); useEffect(() => { api<Page<OpportunityApplication>>("/opportunity-applications/").then((page) => setItems(page.results)).catch(() => {}); }, []); return <main className="tracker-page container"><header><span className="eyebrow">APPLICATION TRACKER</span><h1>Keep every next step visible.</h1><p>Move an opportunity from preparing to applied, then keep track of what follows.</p></header>{items.length ? <div className="tracker-list full">{items.map((item) => <Link href={`/applications/${item.public_id}`} key={item.public_id}><ClipboardCheck size={18} /><div><strong>{item.opportunity.title}</strong><small>{item.next_action || item.opportunity.provider}</small></div><span className={`application-status ${item.status}`}>{item.status}</span>{item.unread_activity_count > 0 && <span className="application-update-indicator"><i />{item.unread_activity_count > 1 ? `${item.unread_activity_count} updates` : "New update"}</span>}<ArrowRight size={16} /></Link>)}</div> : <div className="radar-empty"><ClipboardCheck size={26} /><div><strong>No applications in your tracker.</strong><p>Add an opportunity when you begin preparing for an opportunity.</p></div><Link className="button button-dark compact" href="/matches">See my matches <ArrowRight size={15} /></Link></div>}</main>; }
